ns_rehosts_rng" CHECK ((max_rehosts IS NULL) OR ((max_rehosts >= 0) AND (max_rehosts <= 1000000))), CONSTRAINT "plans_slug_format" CHECK ((slug)::text ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'::text));
